function crmRecord(row, profile) {
  const CHANNELS = { telegram: 'Telegram', whatsapp: 'WhatsApp', messenger: 'Messenger', instagram: 'Instagram', web_chat: 'Website chat', email: 'Email', web_form: 'Website form', lead_ads: 'Facebook lead form' };
  const c = row.contact;
  const facts = c.facts ?? {};
  const [first, ...rest] = String(c.name ?? '').trim().split(/\s+/).filter(Boolean);
  // "$650k", "$400k-$500k", "1.2M": the top of the stated range.
  const amounts = String(facts.budget ?? '').toLowerCase().replace(/,/g, '').match(/\d+(?:\.\d+)?\s*[km]?/g) ?? [];
  const values = amounts.map((a) => parseFloat(a) * (a.endsWith('m') ? 1e6 : a.endsWith('k') ? 1e3 : 1)).filter((n) => n >= 1000);
  const intent = profile.intents[facts.intent]?.label ?? 'New inquiry';
  // A seller's deal is about the home they sell; anyone else's, about where they want to be.
  const place = facts.intent === 'sell' ? (facts.property_area ?? facts.area) : (facts.area ?? facts.property_area);
  const time = (t) => new Intl.DateTimeFormat('en-US', { timeZone: profile.business.timezone, month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(t));
  const who = { lead: c.name || 'Lead', ai: profile.assistant.name, human: 'Team' };
  return {
    first_name: first ?? null,
    last_name: rest.join(' ') || null,
    intent,
    deal_name: `${c.name || 'Lead'} – ${intent}${place ? `, ${place}` : ''}`.slice(0, 200),
    amount: values.length && facts.intent !== 'rent' ? Math.max(...values) : null,
    details: Object.entries(facts).filter(([k]) => k !== 'intent').map(([k, v]) => [k.replace(/_/g, ' '), String(v)]),
    channels: [...new Set(row.messages.map((m) => CHANNELS[m.channel] ?? m.channel))],
    transcript: row.messages.map((m) => ({ time: time(m.sent_at), who: who[m.author] ?? m.author, text: m.text })),
  };
}

// Contact, opportunity and transcript note for GoHighLevel, from what the assistant has learned
// (crmRecord() in core/assistant.mjs, shared with the HubSpot adapter). GoHighLevel notes are plain text.
const profile = JSON.parse($('Read profile text').first().json.text);
const ghl = profile.crm.gohighlevel;
const row = $('Load lead').first().json;
const c = row.contact;
const r = crmRecord(row, profile);

const contact = { locationId: ghl.location_id, source: 'AI Lead Assistant', tags: ['ai-assistant', ...r.channels.map((ch) => ch.toLowerCase())] };
for (const [k, v] of Object.entries({ firstName: r.first_name, lastName: r.last_name, email: c.email, phone: c.phone })) if (v) contact[k] = v;
const opportunity = { name: r.deal_name, status: c.stage === 'lost' ? 'lost' : 'open' };
if (r.amount) opportunity.monetaryValue = r.amount;

const note = [
  `${c.is_hot ? '🔥 Hot lead. ' : ''}${row.summary ?? 'Conversation with the assistant.'}`,
  '',
  `Wants: ${r.intent}`,
  ...r.details.map(([k, v]) => `${k}: ${v}`),
  `Stage: ${c.stage}`,
  ...(c.opted_out_at ? ['Asked not to be contacted'] : []),
  ...(row.conversation.mode === 'human' ? [`Handled by the team: ${row.conversation.handoff_reason ?? ''}`] : []),
  '',
  `Conversation (${r.channels.join(', ')}):`,
  ...r.transcript.map((m) => `[${m.time}] ${m.who}: ${m.text}`),
  '',
  `AI Lead Assistant · conversation #${row.conversation.id} · AI cost $${Number(row.ai_cost_usd).toFixed(4)}`,
].join('\n');

return [{ json: { contact, opportunity, pipeline: ghl.pipeline, stage: ghl.stages[c.stage] ?? ghl.stages.new, location_id: ghl.location_id, note, note_id: row.conversation.crm_refs?.gohighlevel_note ?? null } }];
